investigate.template:
DISPATCH TO: analyzer
ACTION: Investigate
ARTIFACT: ANALYSIS KD
SCOPE: {{scope}}
KDS:
  - {{intent_kd}}
  - {{glob:knowledge/exploration-*{{date}}.md}}
RETURN: knowledge/analysis-{{name}}-{{date}}.md
ACCEPTANCE: Analysis KD produced at knowledge/analysis-{{name}}-{{date}}.md with findings and recommendations

